using namespace spacerad;
namespace {
Json checks=Json::array();
void check(bool ok,const char* name){checks.push_back({{"name",name},{"passed",ok}});if(!ok)throw std::runtime_error(name);std::cout<<"PASS "<<name<<std::endl;}
QPushButton* button(QWidget& w,const char* name){auto* b=w.findChild<QPushButton*>(name);if(!b)throw std::runtime_error("Missing button");return b;}
QByteArray read(const QString& p){QFile f(p);if(!f.open(QIODevice::ReadOnly))throw std::runtime_error("Cannot read UI evidence");return f.readAll();}
void write(const QString& p,const QByteArray& raw){QFile f(p);if(!f.open(QIODevice::WriteOnly|QIODevice::Truncate)||f.write(raw)!=raw.size())throw std::runtime_error("Cannot write UI evidence");}
void pick(QDialog& d,const char* action,const QString& path){bool selected=false;QTimer timer,watchdog;timer.setSingleShot(true);watchdog.setSingleShot(true);QObject::connect(&timer,&QTimer::timeout,&d,[&]{if(auto* f=qobject_cast<QFileDialog*>(QApplication::activeModalWidget())){selected=true;f->setDirectory(QFileInfo(path).absolutePath());f->selectFile(QFileInfo(path).fileName());if(auto* name=f->findChild<QLineEdit*>("fileNameEdit"))name->setText(QFileInfo(path).fileName());QTimer::singleShot(80,f,[f]{QMetaObject::invokeMethod(f,"accept");});}});QObject::connect(&watchdog,&QTimer::timeout,&d,[]{if(auto* w=QApplication::activeModalWidget())w->close();});timer.start(60);watchdog.start(5000);button(d,action)->click();check(selected,"Native study uses actual configuration/export file picker");}
void budget(QDialog& d,int fine){auto* t=d.findChild<QTableWidget*>("spaceradPartitionBands");for(int i=0;i<t->rowCount();++i){t->item(i,2)->setText(QString("%1, %1").arg(fine*2));t->item(i,4)->setText(QString("%1, %1, %1, %1").arg(fine));}}
void run(QDialog& d,bool cancel){auto* s=d.findChild<PartitionStudyService*>();QEventLoop loop;QString error;auto done=QObject::connect(s,&PartitionStudyService::completed,&loop,&QEventLoop::quit);auto failed=QObject::connect(s,&PartitionStudyService::failed,&loop,[&](const QString& e){error=e;loop.quit();});auto state=QObject::connect(s,&PartitionStudyService::stateChanged,&loop,[&](const QString& x){if(x=="cancelled")loop.quit();});QTimer watchdog;watchdog.setSingleShot(true);QObject::connect(&watchdog,&QTimer::timeout,&loop,[&]{error="Native study UI timed out";s->cancel();loop.quit();});watchdog.start(180000);button(d,"spaceradPartitionRun")->click();check(s->running()&&!button(d,"spaceradPartitionRun")->isEnabled()&&!d.findChild<QTableWidget*>("spaceradPartitionBands")->isEnabled(),"Native study locks editing during transport");if(cancel)QTimer::singleShot(30,&d,[&]{button(d,"spaceradPartitionCancel")->click();});loop.exec();QObject::disconnect(done);QObject::disconnect(failed);QObject::disconnect(state);if(!error.isEmpty())throw std::runtime_error(error.toStdString());check(s->state()==(cancel?"cancelled":"completed"),cancel?"Native study cancellation reaches terminal state":"Native study completes real transport");}
}
int main(int argc,char** argv){QSurfaceFormat::setDefaultFormat(QVTKOpenGLNativeWidget::defaultFormat());QCoreApplication::setAttribute(Qt::AA_DontUseNativeDialogs);QApplication app(argc,argv);if(argc!=4)return 2;QString runtime=QString::fromLocal8Bit(argv[1]),input=QString::fromLocal8Bit(argv[2]),out=QFileInfo(QString::fromLocal8Bit(argv[3])).absoluteFilePath();if(QFileInfo::exists(out)||!QDir().mkpath(out))return 2;bool passed=false;
try{WorkbenchWidget host;host.resize(1150,850);host.setRuntime(loadRuntimeFile(runtime));auto initial=engine::loadProjectFile(input).project;initial.events=100;host.setProject(initial);host.show();app.processEvents();{QEventLoop seedLoop;QString seedError;QTimer timer;timer.setSingleShot(true);auto done=QObject::connect(&host,&WorkbenchWidget::resultReady,&seedLoop,&QEventLoop::quit);auto failed=QObject::connect(host.service(),&AnalysisService::failed,&seedLoop,[&](const QString& e){seedError=e;seedLoop.quit();});QObject::connect(&timer,&QTimer::timeout,&seedLoop,[&]{seedError="Host fixture timed out";host.cancel();seedLoop.quit();});timer.start(30000);host.runTo(out+"/host-job");seedLoop.exec();QObject::disconnect(done);QObject::disconnect(failed);if(!seedError.isEmpty())throw std::runtime_error(seedError.toStdString());}check(!host.acceptedResult().isEmpty(),"Host starts with a real previously accepted result");auto before=host.project().toJson();auto accepted=host.acceptedResult();int changed=0,ready=0;QObject::connect(&host,&WorkbenchWidget::projectChanged,&host,[&]{++changed;});QObject::connect(&host,&WorkbenchWidget::resultReady,&host,[&](const QByteArray&){++ready;});button(host,"spaceradPartitionStudy")->click();app.processEvents();auto* d=host.findChild<QDialog*>("spaceradPartitionDialog");check(d&&d->isVisible()&&!d->isModal(),"Shared workbench opens independent native partition window");auto* t=d->findChild<QTableWidget*>("spaceradPartitionBands");check(t->rowCount()==2,"Native plan includes both physical incident species");auto cuts=t->item(0,3)->text();t->item(0,3)->setText("999");check(!button(*d,"spaceradPartitionRun")->isEnabled(),"Invalid energy partition disables launch");t->item(0,3)->setText(cuts);auto history=t->item(0,2)->text();t->item(0,2)->setText("2,2");check(!button(*d,"spaceradPartitionRun")->isEnabled(),"Mismatched partition budgets disable launch");t->item(0,2)->setText(history);budget(*d,50);check(d->findChild<QLabel*>("spaceradPartitionPreview")->text().contains("3200"),"Native preview includes every thickness species and replica");
    pick(*d,"spaceradPartitionSaveConfig",out+"/config.json");check(QFileInfo::exists(out+"/config.json"),"Native study configuration saves to new file");auto saved=Json::parse(read(out+"/config.json").toStdString());budget(*d,60);pick(*d,"spaceradPartitionImportConfig",out+"/config.json");pick(*d,"spaceradPartitionSaveConfig",out+"/config-roundtrip.json");check(Json::parse(read(out+"/config-roundtrip.json").toStdString())==saved,"Native configuration roundtrip preserves precise cuts and budgets");
    d->findChild<QLineEdit*>("spaceradPartitionOutput")->setText(out+"/job");run(*d,false);auto* s=d->findChild<PartitionStudyService*>();auto report=Json::parse(s->result().toStdString());check(report.at("scans").size()==24&&report.at("rows").size()==12&&report.at("total_histories")==3200,"Native whole-spacecraft study completes 48 actual jobs");auto* results=d->findChild<QTableWidget*>("spaceradPartitionEstimates");check(results->rowCount()==48,"Native result table exposes all target thickness and seed estimates");results->setCurrentCell(2,0);app.processEvents();check(d->findChild<QTableWidget*>("spaceradPartitionComponents")->rowCount()==8&&d->findChild<QTableWidget*>("spaceradPartitionPairs")->rowCount()==6,"Selecting fine result exposes all energy bands and pair comparisons");bool zero=false,boundsNull=true,uncertaintyGuarded=true;for(const auto& row:report.at("rows")){bool hasZero=false;for(const auto& e:row.at("estimates"))for(const auto& c:e.at("components"))if(c.at("nonzero_histories")==0){hasZero=true;zero=true;boundsNull&=c.at("dose_upper_bound_Gy").is_null();}if(hasZero)uncertaintyGuarded&=row.at("mean_standard_error_Gy").is_null()&&!row.at("support_screen_passed").get<bool>();}check(zero,"Small native spacecraft study exercises zero-support display");check(boundsNull,"Zero-event probabilities are never converted to dose bounds");check(uncertaintyGuarded,"Native full uncertainty stays unknown for every zero-support target");check(d->findChild<QProgressBar*>("spaceradPartitionProgress")->value()==1000,"Complete native study reaches full progress");
    pick(*d,"spaceradPartitionCsv",out+"/export.csv");pick(*d,"spaceradPartitionJson",out+"/export.json");check(read(out+"/export.csv")==partitionStudyCsv(report)&&Json::parse(read(out+"/export.json").toStdString())==report,"Native exports retain accepted aggregate statistics");
    d->resize(680,520);app.processEvents();auto* scroll=d->findChild<QScrollArea*>("spaceradPartitionScroll");scroll->ensureWidgetVisible(button(*d,"spaceradPartitionCsv"));app.processEvents();check(scroll->verticalScrollBar()->maximum()>0&&scroll->viewport()->rect().contains(button(*d,"spaceradPartitionCsv")->mapTo(scroll->viewport(),button(*d,"spaceradPartitionCsv")->rect().center())),"Small native windows scroll to study exports");d->resize(1240,1000);scroll->verticalScrollBar()->setValue(0);app.processEvents();check(d->grab().save(out+"/study.png"),"Native partition window screenshot saved");
    check(host.project().toJson()==before&&host.acceptedResult()==accepted&&changed==0&&ready==0&&!host.service()->running(),"Native study preserves host project accepted result and signals");budget(*d,1000000);d->findChild<QLineEdit*>("spaceradPartitionOutput")->setText(out+"/cancel");run(*d,true);check(s->result().isEmpty()&&loadPartitionStudy(out+"/cancel").at("status")=="cancelled"&&results->rowCount()==0,"Cancelled native UI never exposes full accepted rows");QPointer<QDialog> old=d;d->close();QCoreApplication::sendPostedEvents(nullptr,QEvent::DeferredDelete);app.processEvents();check(old.isNull(),"Native study dialog is destroyed on close");
    host.setRuntime({});host.showPartitionStudy(out+"/job");app.processEvents();auto* historical=host.findChild<QDialog*>("spaceradPartitionDialog");check(historical&&historical->findChild<QTableWidget*>("spaceradPartitionEstimates")->rowCount()==48,"Historical native study opens without configured Worker");historical->findChild<PartitionStudyService*>()->configure(loadRuntimeFile(runtime));budget(*historical,1000000);historical->findChild<QLineEdit*>("spaceradPartitionOutput")->setText(out+"/close-active");button(*historical,"spaceradPartitionRun")->click();QPointer<QDialog> closing=historical;QEventLoop loop;QObject::connect(historical,&QObject::destroyed,&loop,&QEventLoop::quit);QTimer::singleShot(30,&loop,[&]{if(closing)closing->close();});QTimer::singleShot(5000,&loop,&QEventLoop::quit);loop.exec();check(closing.isNull()&&loadPartitionStudy(out+"/close-active").at("status")=="cancelled","Closing active native study terminates transport and records cancellation");
    auto raw=read(out+"/job/study.csv");write(out+"/job/study.csv",raw+"tamper");host.showPartitionStudy(out+"/job");app.processEvents();auto* tampered=host.findChild<QDialog*>("spaceradPartitionDialog");check(tampered->findChild<QTableWidget*>("spaceradPartitionEstimates")->rowCount()==0&&!tampered->findChild<QLabel*>("spaceradPartitionNotice")->text().isEmpty(),"Native viewer rejects altered archive without displaying stale results");write(out+"/job/study.csv",raw);tampered->close();QCoreApplication::sendPostedEvents(nullptr,QEvent::DeferredDelete);auto* ephemeral=new WorkbenchWidget;ephemeral->setProject(initial);ephemeral->showPartitionStudy();app.processEvents();QPointer<WorkbenchWidget> owner=ephemeral;QPointer<QDialog> pickerOwner=ephemeral->findChild<QDialog*>("spaceradPartitionDialog");QTimer::singleShot(100,&app,[ephemeral]{delete ephemeral;});button(*pickerOwner,"spaceradPartitionImportConfig")->click();check(owner.isNull()&&pickerOwner.isNull(),"Host destruction during file picker returns without stale dialog access");passed=true;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';}write(out+"/summary.json",QByteArray::fromStdString(Json{{"passed",passed},{"checks",checks}}.dump(2)));std::cout<<checks.size()<<" native partition UI checks; passed="<<passed<<'\n';return passed?0:1;}
